-- Generated by tools/Build-Scripts.ps1 from DataDiscoveryAndClassification/. Don't edit it by hand.
-- Installs the DC schema into the current database. Run it with sqlcmd or in SSMS.
SET NOCOUNT ON;
GO
IF OBJECT_ID(N'sys.sensitivity_classifications') IS NULL
BEGIN
    RAISERROR(N'DataDiscoveryAndClassification needs SQL Server 2019 or later, or Azure SQL.', 16, 1);
    SET NOEXEC ON;
END
ELSE IF (SELECT compatibility_level FROM sys.databases WHERE database_id = DB_ID()) < 130
BEGIN
    RAISERROR(N'DataDiscoveryAndClassification needs database compatibility level 130 or higher (it reads JSON).', 16, 1);
    SET NOEXEC ON;
END
ELSE IF SCHEMA_ID(N'DC') IS NOT NULL
BEGIN
    RAISERROR(N'The DC schema exists already. Run install/Uninstall.sql first.', 16, 1);
    SET NOEXEC ON;
END
GO

-- Schema/DC.sql
CREATE SCHEMA [DC] AUTHORIZATION [dbo];
GO

-- Tables/SensitiveName.sql
-- Sensitivity labels: how sensitive the data in a column is.
CREATE TABLE [DC].[SensitiveName]
(
    [LabelId]    UNIQUEIDENTIFIER NOT NULL,
    [LabelName]  NVARCHAR (128)   NOT NULL,
    [LabelOrder] INT              NOT NULL,
    [LabelRank]  NVARCHAR (10)    NOT NULL CONSTRAINT [DF_SensitiveName_LabelRank] DEFAULT (N'NONE'),
    CONSTRAINT [PK_SensitiveName] PRIMARY KEY CLUSTERED ([LabelId]),
    CONSTRAINT [CK_SensitiveName_LabelRank] CHECK ([LabelRank] IN (N'NONE', N'LOW', N'MEDIUM', N'HIGH', N'CRITICAL'))
);
GO

CREATE UNIQUE INDEX [IX_SensitiveName_LabelName] ON [DC].[SensitiveName] ([LabelName]);
GO

-- Tables/InformationType.sql
-- Information types: what kind of data a column holds, and the label recommended for it.
-- When a column matches keywords of several types, the type with the lowest InfoTypeOrder wins.
CREATE TABLE [DC].[InformationType]
(
    [InfoTypeId]         UNIQUEIDENTIFIER NOT NULL,
    [InfoTypeName]       NVARCHAR (128)   NOT NULL,
    [InfoTypeOrder]      INT              NOT NULL,
    [RecommendedLabelId] UNIQUEIDENTIFIER NULL,
    CONSTRAINT [PK_InformationType] PRIMARY KEY CLUSTERED ([InfoTypeId]),
    CONSTRAINT [FK_InformationType_SensitiveName] FOREIGN KEY ([RecommendedLabelId]) REFERENCES [DC].[SensitiveName] ([LabelId])
);
GO

CREATE UNIQUE INDEX [IX_InformationType_InfoTypeName] ON [DC].[InformationType] ([InfoTypeName]);
GO

-- Tables/KeyWords.sql
-- Column-name patterns (LIKE syntax, compared case-insensitively) that point to an information type.
-- CanBeNumeric = 0 skips columns of numeric types, so that AddressId isn't taken for an address.
CREATE TABLE [DC].[KeyWords]
(
    [InfoTypeId]   UNIQUEIDENTIFIER NOT NULL,
    [KeywordName]  NVARCHAR (128)   COLLATE Latin1_General_100_BIN2 NOT NULL,
    [CanBeNumeric] BIT              NOT NULL,
    CONSTRAINT [PK_KeyWords] PRIMARY KEY CLUSTERED ([InfoTypeId], [KeywordName]),
    CONSTRAINT [FK_KeyWords_InformationType] FOREIGN KEY ([InfoTypeId]) REFERENCES [DC].[InformationType] ([InfoTypeId]) ON DELETE CASCADE
);
GO

-- Functions/AddClassificationStatement.sql
-- Builds one ADD SENSITIVITY CLASSIFICATION statement. Names are quoted and values escaped,
-- so any schema, table, column or label name is safe. NULL options are left out, and a rank
-- outside NONE, LOW, MEDIUM, HIGH and CRITICAL is ignored. Returns NULL when there is nothing to add.
CREATE FUNCTION [DC].[AddClassificationStatement]
(
    @SchemaName        SYSNAME,
    @TableName         SYSNAME,
    @ColumnName        SYSNAME,
    @Label             NVARCHAR (128),
    @LabelId           NVARCHAR (128),
    @InformationType   NVARCHAR (128),
    @InformationTypeId NVARCHAR (128),
    @Rank              NVARCHAR (10)
)
RETURNS NVARCHAR (MAX)
AS
BEGIN
    DECLARE @options AS NVARCHAR (MAX) = CONCAT_WS(
        N', ',
        N'LABEL = N''' + REPLACE(@Label, N'''', N'''''') + N'''',
        N'LABEL_ID = N''' + REPLACE(@LabelId, N'''', N'''''') + N'''',
        N'INFORMATION_TYPE = N''' + REPLACE(@InformationType, N'''', N'''''') + N'''',
        N'INFORMATION_TYPE_ID = N''' + REPLACE(@InformationTypeId, N'''', N'''''') + N'''',
        CASE WHEN UPPER(@Rank) IN (N'NONE', N'LOW', N'MEDIUM', N'HIGH', N'CRITICAL') THEN N'RANK = ' + UPPER(@Rank) END
    );

    IF @options = N''
        RETURN NULL;

    RETURN N'ADD SENSITIVITY CLASSIFICATION TO '
        + QUOTENAME(@SchemaName) + N'.' + QUOTENAME(@TableName) + N'.' + QUOTENAME(@ColumnName)
        + N' WITH (' + @options + N');';
END;
GO

-- Views/GetMatchingColumns.sql
-- Every column of a user table whose name matches a keyword, with the keyword's information type.
-- Left out: the DC schema, bit columns, computed columns and history tables (SQL Server refuses to
-- classify those two; a history table takes the classification of its current table), and numeric
-- columns for keywords that can't be numeric.
CREATE VIEW [DC].[GetMatchingColumns]
AS
SELECT
    S.name        AS SchemaName,
    T.name        AS TableName,
    C.name        AS ColumnName,
    T.object_id   AS TableObjectId,
    C.column_id   AS ColumnId,
    K.InfoTypeId  AS InfoTypeId,
    K.KeywordName AS KeywordName
FROM sys.tables AS T
    INNER JOIN sys.schemas AS S
        ON S.schema_id = T.schema_id
    INNER JOIN sys.columns AS C
        ON C.object_id = T.object_id
    INNER JOIN DC.KeyWords AS K
        ON LOWER(C.name) COLLATE Latin1_General_100_BIN2 LIKE LOWER(K.KeywordName) COLLATE Latin1_General_100_BIN2
WHERE T.is_ms_shipped = 0
    AND T.is_external = 0
    AND T.temporal_type <> 1
    AND C.is_computed = 0
    AND S.name <> N'DC'
    AND TYPE_NAME(C.system_type_id) <> N'bit'
    AND (K.CanBeNumeric = 1
        OR TYPE_NAME(C.system_type_id) NOT IN (N'bigint', N'decimal', N'float', N'int', N'money', N'numeric', N'real', N'smallint', N'smallmoney', N'tinyint'));
GO

-- Views/GetClassifiedColumns.sql
-- Every classified column, as SQL Server stores it in sys.sensitivity_classifications.
-- Reading it needs the VIEW ANY SENSITIVITY CLASSIFICATION permission. The casts are for
-- SQL Server 2019, where the catalog view returns these columns as sql_variant.
CREATE VIEW [DC].[GetClassifiedColumns]
AS
SELECT
    SCHEMA_NAME(O.schema_id)                             AS SchemaName,
    O.name                                               AS TableName,
    C.name                                               AS ColumnName,
    CAST(SC.information_type AS NVARCHAR (128))          AS InformationType,
    CAST(SC.information_type_id AS NVARCHAR (128))       AS InformationTypeId,
    CAST(SC.label AS NVARCHAR (128))                     AS SensitivityLabel,
    CAST(SC.label_id AS NVARCHAR (128))                  AS SensitivityLabelId,
    CAST(SC.rank_desc AS NVARCHAR (10))                  AS SensitivityRank,
    CAST(CASE WHEN T.temporal_type = 1 THEN 1 ELSE 0 END AS BIT) AS IsHistoryTable
FROM sys.sensitivity_classifications AS SC
    INNER JOIN sys.objects AS O
        ON O.object_id = SC.major_id
    INNER JOIN sys.columns AS C
        ON C.object_id = SC.major_id
        AND C.column_id = SC.minor_id
    LEFT JOIN sys.tables AS T
        ON T.object_id = O.object_id
WHERE SC.class = 1;
GO

-- Views/GetIntermediateResults.sql
-- The suggestions: one information type and its recommended label for each matching column
-- that isn't classified yet. DC.AcceptSuggestions applies them.
CREATE VIEW [DC].[GetIntermediateResults]
AS
WITH Ranked AS
(
    SELECT
        MC.SchemaName,
        MC.TableName,
        MC.ColumnName,
        MC.TableObjectId,
        MC.ColumnId,
        IT.InfoTypeId,
        IT.InfoTypeName,
        SN.LabelId,
        SN.LabelName,
        SN.LabelRank,
        ROW_NUMBER() OVER (
            PARTITION BY MC.TableObjectId, MC.ColumnId
            ORDER BY IT.InfoTypeOrder, IT.InfoTypeName) AS Choice
    FROM DC.GetMatchingColumns AS MC
        INNER JOIN DC.InformationType AS IT
            ON IT.InfoTypeId = MC.InfoTypeId
        LEFT JOIN DC.SensitiveName AS SN
            ON SN.LabelId = IT.RecommendedLabelId
)
SELECT
    R.SchemaName,
    R.TableName,
    R.ColumnName,
    R.InfoTypeId   AS InformationTypeId,
    R.InfoTypeName AS InformationTypeName,
    R.LabelId      AS SensitivityLabelId,
    R.LabelName    AS SensitivityLabelName,
    R.LabelRank    AS SensitivityRank
FROM Ranked AS R
WHERE R.Choice = 1
    AND NOT EXISTS
    (
        SELECT 1
        FROM sys.sensitivity_classifications AS SC
        WHERE SC.class = 1
            AND SC.major_id = R.TableObjectId
            AND SC.minor_id = R.ColumnId
    );
GO

-- Views/GetLegacyClassifiedColumns.sql
-- Columns classified the way SSMS did it before SQL Server 2019, and version 1 of this project:
-- in the extended properties sys_information_type_name, sys_information_type_id,
-- sys_sensitivity_label_name and sys_sensitivity_label_id.
CREATE VIEW [DC].[GetLegacyClassifiedColumns]
AS
SELECT
    SCHEMA_NAME(O.schema_id)          AS SchemaName,
    O.name                            AS TableName,
    C.name                            AS ColumnName,
    CAST(ITN.value AS NVARCHAR (128)) AS InformationType,
    CAST(ITI.value AS NVARCHAR (128)) AS InformationTypeId,
    CAST(SLN.value AS NVARCHAR (128)) AS SensitivityLabel,
    CAST(SLI.value AS NVARCHAR (128)) AS SensitivityLabelId,
    C.is_computed                     AS IsComputed,
    CAST(CASE WHEN T.temporal_type = 1 THEN 1 ELSE 0 END AS BIT) AS IsHistoryTable,
    CAST(CASE WHEN EXISTS
        (
            SELECT 1
            FROM sys.sensitivity_classifications AS SC
            WHERE SC.class = 1
                AND SC.major_id = EP.major_id
                AND SC.minor_id = EP.minor_id
        ) THEN 1 ELSE 0 END AS BIT) AS IsClassified
FROM
(
    SELECT DISTINCT major_id, minor_id
    FROM sys.extended_properties
    WHERE class = 1
        AND minor_id > 0
        AND name IN (N'sys_information_type_name', N'sys_information_type_id', N'sys_sensitivity_label_name', N'sys_sensitivity_label_id')
) AS EP
    INNER JOIN sys.objects AS O
        ON O.object_id = EP.major_id
    INNER JOIN sys.columns AS C
        ON C.object_id = EP.major_id
        AND C.column_id = EP.minor_id
    LEFT JOIN sys.tables AS T
        ON T.object_id = O.object_id
    LEFT JOIN sys.extended_properties AS ITN
        ON ITN.class = 1 AND ITN.major_id = EP.major_id AND ITN.minor_id = EP.minor_id AND ITN.name = N'sys_information_type_name'
    LEFT JOIN sys.extended_properties AS ITI
        ON ITI.class = 1 AND ITI.major_id = EP.major_id AND ITI.minor_id = EP.minor_id AND ITI.name = N'sys_information_type_id'
    LEFT JOIN sys.extended_properties AS SLN
        ON SLN.class = 1 AND SLN.major_id = EP.major_id AND SLN.minor_id = EP.minor_id AND SLN.name = N'sys_sensitivity_label_name'
    LEFT JOIN sys.extended_properties AS SLI
        ON SLI.class = 1 AND SLI.major_id = EP.major_id AND SLI.minor_id = EP.minor_id AND SLI.name = N'sys_sensitivity_label_id'
WHERE O.type = 'U';
GO

-- Procedures/ImportPolicy.sql
-- Replaces the labels, information types and keywords with those of an Information Protection
-- policy file, the JSON that SSMS exports and reads (Tasks > Data Discovery and Classification).
-- Disabled labels and information types and excluded keywords are left out.
-- Classifications already on columns aren't touched.
CREATE PROCEDURE [DC].[ImportPolicy]
    @Policy NVARCHAR (MAX)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    -- A file read as text may start with a byte order mark.
    IF LEFT(@Policy, 1) = NCHAR(65279)
        SET @Policy = STUFF(@Policy, 1, 1, N'');

    IF ISJSON(@Policy) = 0
        OR JSON_QUERY(@Policy, N'$.Labels') IS NULL
        OR JSON_QUERY(@Policy, N'$.InformationTypes') IS NULL
        THROW 50000, N'The policy must be a JSON object with Labels and InformationTypes, like the Information Protection policy file SSMS exports.', 1;

    BEGIN TRANSACTION;

    DELETE FROM DC.KeyWords;
    DELETE FROM DC.InformationType;
    DELETE FROM DC.SensitiveName;

    INSERT INTO DC.SensitiveName (LabelId, LabelName, LabelOrder, LabelRank)
    SELECT
        CONVERT(UNIQUEIDENTIFIER, L.[key]),
        D.DisplayName,
        D.[Order],
        UPPER(ISNULL(D.[Rank], N'None'))
    FROM OPENJSON(@Policy, N'$.Labels') AS L
        CROSS APPLY OPENJSON(L.value)
        WITH
        (
            DisplayName NVARCHAR (128),
            [Rank]      NVARCHAR (10),
            [Order]     INT,
            Enabled     BIT
        ) AS D
    WHERE ISNULL(D.Enabled, 1) = 1;

    INSERT INTO DC.InformationType (InfoTypeId, InfoTypeName, InfoTypeOrder, RecommendedLabelId)
    SELECT
        CONVERT(UNIQUEIDENTIFIER, I.[key]),
        D.DisplayName,
        D.[Order],
        SN.LabelId
    FROM OPENJSON(@Policy, N'$.InformationTypes') AS I
        CROSS APPLY OPENJSON(I.value)
        WITH
        (
            DisplayName        NVARCHAR (128),
            [Order]            INT,
            RecommendedLabelId UNIQUEIDENTIFIER,
            Enabled            BIT
        ) AS D
        LEFT JOIN DC.SensitiveName AS SN
            ON SN.LabelId = D.RecommendedLabelId
    WHERE ISNULL(D.Enabled, 1) = 1;

    INSERT INTO DC.KeyWords (InfoTypeId, KeywordName, CanBeNumeric)
    SELECT
        IT.InfoTypeId,
        K.Pattern COLLATE Latin1_General_100_BIN2,
        MAX(CAST(ISNULL(K.CanBeNumeric, 1) AS INT))
    FROM OPENJSON(@Policy, N'$.InformationTypes') AS I
        INNER JOIN DC.InformationType AS IT
            ON IT.InfoTypeId = CONVERT(UNIQUEIDENTIFIER, I.[key])
        CROSS APPLY OPENJSON(I.value, N'$.Keywords')
        WITH
        (
            Pattern      NVARCHAR (128),
            CanBeNumeric BIT,
            Excluded     BIT
        ) AS K
    WHERE K.Pattern IS NOT NULL
        AND ISNULL(K.Excluded, 0) = 0
    GROUP BY IT.InfoTypeId, K.Pattern COLLATE Latin1_General_100_BIN2;

    COMMIT TRANSACTION;

    DECLARE @summary AS NVARCHAR (200) = CONCAT(
        N'Imported ', (SELECT COUNT(*) FROM DC.SensitiveName), N' labels, ',
        (SELECT COUNT(*) FROM DC.InformationType), N' information types and ',
        (SELECT COUNT(*) FROM DC.KeyWords), N' keywords.');
    PRINT @summary;
END;
GO

-- Procedures/AcceptSuggestions.sql
-- Classifies every column in DC.GetIntermediateResults with its suggested information type,
-- label and rank. All the columns are classified, or none.
-- Needs the ALTER ANY SENSITIVITY CLASSIFICATION permission (implied by ALTER on the database).
CREATE PROCEDURE [DC].[AcceptSuggestions]
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @statement AS NVARCHAR (MAX);
    DECLARE @classified AS INT = 0;

    DECLARE Suggestions CURSOR LOCAL STATIC READ_ONLY FORWARD_ONLY FOR
        SELECT DC.AddClassificationStatement(
            SchemaName,
            TableName,
            ColumnName,
            SensitivityLabelName,
            LOWER(CONVERT(NVARCHAR (36), SensitivityLabelId)),
            InformationTypeName,
            LOWER(CONVERT(NVARCHAR (36), InformationTypeId)),
            SensitivityRank)
        FROM DC.GetIntermediateResults;

    BEGIN TRANSACTION;

    OPEN Suggestions;
    FETCH NEXT FROM Suggestions INTO @statement;
    WHILE @@FETCH_STATUS = 0
    BEGIN
        EXECUTE sys.sp_executesql @statement;
        SET @classified += 1;
        FETCH NEXT FROM Suggestions INTO @statement;
    END;
    CLOSE Suggestions;
    DEALLOCATE Suggestions;

    COMMIT TRANSACTION;

    PRINT CONCAT(N'Classified ', @classified, N' column(s).');
END;
GO

-- Procedures/RemoveClassification.sql
-- Removes the classification of every classified column in the database, whoever added it
-- (this project, SSMS or T-SQL). History tables lose theirs with their current table.
-- Needs the ALTER ANY SENSITIVITY CLASSIFICATION permission (implied by ALTER on the database).
CREATE PROCEDURE [DC].[RemoveClassification]
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @statement AS NVARCHAR (MAX);
    DECLARE @removed AS INT = 0;

    DECLARE Classified CURSOR LOCAL STATIC READ_ONLY FORWARD_ONLY FOR
        SELECT N'DROP SENSITIVITY CLASSIFICATION FROM '
            + QUOTENAME(SchemaName) + N'.' + QUOTENAME(TableName) + N'.' + QUOTENAME(ColumnName) + N';'
        FROM DC.GetClassifiedColumns
        WHERE IsHistoryTable = 0;

    BEGIN TRANSACTION;

    OPEN Classified;
    FETCH NEXT FROM Classified INTO @statement;
    WHILE @@FETCH_STATUS = 0
    BEGIN
        EXECUTE sys.sp_executesql @statement;
        SET @removed += 1;
        FETCH NEXT FROM Classified INTO @statement;
    END;
    CLOSE Classified;
    DEALLOCATE Classified;

    COMMIT TRANSACTION;

    PRINT CONCAT(N'Removed the classification of ', @removed, N' column(s).');
END;
GO

-- Procedures/MigrateLegacyClassification.sql
-- Moves classifications kept in extended properties (SSMS before SQL Server 2019, and version 1
-- of this project) into sys.sensitivity_classifications. A column that is classified there
-- already keeps its classification. The rank comes from DC.SensitiveName when the label is in it.
-- With @DropLegacy = 1 the four extended properties are dropped afterwards, from every column.
CREATE PROCEDURE [DC].[MigrateLegacyClassification]
    @DropLegacy BIT = 0
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @statement AS NVARCHAR (MAX);
    DECLARE @migrated AS INT = 0;
    DECLARE @dropped AS INT = 0;
    DECLARE @schemaName AS SYSNAME;
    DECLARE @tableName AS SYSNAME;
    DECLARE @columnName AS SYSNAME;
    DECLARE @propertyName AS SYSNAME;

    DECLARE Legacy CURSOR LOCAL STATIC READ_ONLY FORWARD_ONLY FOR
        SELECT DC.AddClassificationStatement(
            L.SchemaName,
            L.TableName,
            L.ColumnName,
            L.SensitivityLabel,
            L.SensitivityLabelId,
            L.InformationType,
            L.InformationTypeId,
            SN.LabelRank)
        FROM DC.GetLegacyClassifiedColumns AS L
            LEFT JOIN DC.SensitiveName AS SN
                ON SN.LabelId = TRY_CONVERT(UNIQUEIDENTIFIER, L.SensitivityLabelId)
                OR (L.SensitivityLabelId IS NULL AND SN.LabelName = L.SensitivityLabel)
        WHERE L.IsClassified = 0
            AND L.IsComputed = 0
            AND L.IsHistoryTable = 0;

    DECLARE Properties CURSOR LOCAL STATIC READ_ONLY FORWARD_ONLY FOR
        SELECT SCHEMA_NAME(O.schema_id), O.name, C.name, EP.name
        FROM sys.extended_properties AS EP
            INNER JOIN sys.objects AS O
                ON O.object_id = EP.major_id
            INNER JOIN sys.columns AS C
                ON C.object_id = EP.major_id
                AND C.column_id = EP.minor_id
        WHERE EP.class = 1
            AND O.type = 'U'
            AND EP.name IN (N'sys_information_type_name', N'sys_information_type_id', N'sys_sensitivity_label_name', N'sys_sensitivity_label_id');

    BEGIN TRANSACTION;

    OPEN Legacy;
    FETCH NEXT FROM Legacy INTO @statement;
    WHILE @@FETCH_STATUS = 0
    BEGIN
        IF @statement IS NOT NULL
        BEGIN
            EXECUTE sys.sp_executesql @statement;
            SET @migrated += 1;
        END;
        FETCH NEXT FROM Legacy INTO @statement;
    END;
    CLOSE Legacy;
    DEALLOCATE Legacy;

    IF @DropLegacy = 1
    BEGIN
        OPEN Properties;
        FETCH NEXT FROM Properties INTO @schemaName, @tableName, @columnName, @propertyName;
        WHILE @@FETCH_STATUS = 0
        BEGIN
            EXECUTE sys.sp_dropextendedproperty
                @name = @propertyName,
                @level0type = N'SCHEMA', @level0name = @schemaName,
                @level1type = N'TABLE', @level1name = @tableName,
                @level2type = N'COLUMN', @level2name = @columnName;
            SET @dropped += 1;
            FETCH NEXT FROM Properties INTO @schemaName, @tableName, @columnName, @propertyName;
        END;
        CLOSE Properties;
    END;
    DEALLOCATE Properties;

    COMMIT TRANSACTION;

    PRINT CONCAT(N'Migrated ', @migrated, N' column(s); dropped ', @dropped, N' extended propert', IIF(@dropped = 1, N'y', N'ies'), N'.');
END;
GO

